const txts=["Consolidando logs...","Enviando traza a nodo central...","Generando reporte de infracción...","Finalizando conexión segura..."];let i=0;const tI=setInterval(()=>{if(i<txts.length){const el=document.getElementById('dynamic-text');if(el){el.innerText=txts[i];i++;}}else{clearInterval(tI);setTimeout(()=>{window.location.href="https://es.wikipedia.org/wiki/Phishing";},2000);}},2000);
